"""Pydantic schema definitions for the realtime collaboration protocol.

Version 1 (v1) of the protocol defines three primary message types:

* ``Welcome`` – sent by the server when a client joins a document.
* ``Operation`` – insert or delete operations generated by the client.
* ``Error`` – server‑side error response.

All messages share a ``type`` discriminator which enables FastAPI to parse them
automatically via ``Union``.
"""

from __future__ import annotations

from enum import Enum
from typing import Literal, Union, Any, Dict, List, Optional

from pydantic import BaseModel, Field, validator


class MessageType(str, Enum):
    WELCOME = "welcome"
    OPERATION = "op"
    ERROR = "error"
    PING = "ping"
    PONG = "pong"
    PRESENCE = "presence"
    UNDO = "undo"


class BaseMessage(BaseModel):
    type: MessageType


class WelcomeMessage(BaseMessage):
    type: Literal[MessageType.WELCOME] = MessageType.WELCOME
    doc_id: str
    user: str
    server_seq: int = 0
    # ``content`` can be injected later if you want to send the whole document
    # on join – omitted for now to keep the payload small.


class OperationPayload(BaseModel):
    op: Literal["insert", "delete"]
    # ``pos`` is a byte offset into the UTF‑8 string.  For simplicity we treat the
    # document as a Python ``str`` and use the character index.
    pos: int = Field(..., ge=0)
    # ``text`` is required for inserts, ``length`` for deletes.
    text: Optional[str] = None
    length: Optional[int] = None

    @validator("text", always=True)
    def check_text_for_insert(cls, v, values):  # noqa: D401
        """Validate that ``text`` is present for ``insert`` operations."""
        if values.get("op") == "insert" and (v is None or v == ""):
            raise ValueError("'text' required for insert op")
        return v

    @validator("length", always=True)
    def check_length_for_delete(cls, v, values):  # noqa: D401
        """Validate that ``length`` is present for ``delete`` operations."""
        if values.get("op") == "delete" and (v is None or v <= 0):
            raise ValueError("'length' must be >0 for delete op")
        return v


class OperationMessage(BaseMessage):
    type: Literal[MessageType.OPERATION] = MessageType.OPERATION
    doc_id: str
    client_seq: int = Field(..., ge=0)
    # ``origin`` is the user_id who generated the operation – filled in by the
    # server before broadcast.
    origin: Optional[str] = None
    payload: OperationPayload
    # Optional HMAC signature (base64) over the *entire* JSON message (including
    # ``type``, ``doc_id``, ``client_seq``, ``payload``).  The server verifies it
    # before applying the operation.
    signature: Optional[str] = None


class ErrorMessage(BaseMessage):
    type: Literal[MessageType.ERROR] = MessageType.ERROR
    code: int
    msg: str
    details: Optional[Dict[str, Any]] = None


Message = Union[WelcomeMessage, OperationMessage, ErrorMessage]
# ---------------------------------------------------------------------------
# Presence / awareness messages – lightweight cursor broadcasting.
# ---------------------------------------------------------------------------


class PresenceMessage(BaseMessage):
    type: Literal[MessageType.PRESENCE] = MessageType.PRESENCE
    doc_id: str
    user: str
    # Simple cursor position (character offset) and optional selection length.
    cursor_pos: int = Field(..., ge=0)
    selection_len: Optional[int] = Field(default=None, ge=0)

    # Presence messages are not signed – they are low‑cost and throttled server‑side.

Message = Union[WelcomeMessage, OperationMessage, ErrorMessage, PresenceMessage]
# ---------------------------------------------------------------------------
# Undo / Redo messages – lightweight commands that trigger server‑side history
# traversal.  They carry a ``target_version`` the client wishes to revert to or
# reapply.  The server validates ACLs, verifies the optional HMAC signature, and
# broadcasts the resulting operation(s) to all peers.
# ---------------------------------------------------------------------------


class UndoMessage(BaseMessage):
    type: Literal[MessageType.UNDO] = MessageType.UNDO
    doc_id: str
    # The version the client wants to revert to (must be < current version).
    target_version: int = Field(..., ge=0)
    # Optional HMAC signature over the JSON payload (including ``type`` and ``target_version``).
    signature: Optional[str] = None


Message = Union[WelcomeMessage, OperationMessage, ErrorMessage, PresenceMessage, UndoMessage]
# ---------------------------------------------------------------------------
# Redo support – the client can request to re‑apply operations that were undone.
# It mirrors ``UndoMessage`` but targets a version newer than the current one.
# ---------------------------------------------------------------------------


class RedoMessage(BaseMessage):
    type: Literal[MessageType.UNDO] = MessageType.UNDO  # Reuse the same type for simplicity
    doc_id: str
    # ``target_version`` must be > current version.
    target_version: int = Field(..., ge=0)
    signature: Optional[str] = None


Message = Union[WelcomeMessage, OperationMessage, ErrorMessage, PresenceMessage, UndoMessage, RedoMessage]
